import java.sql.*; import java.util.Scanner;
public class LibraryJDBC { static final String URL="jdbc:mysql://localhost:3306/college",USER="root",PASSWORD="root"; static Connection getConnection()throws SQLException{return DriverManager.getConnection(URL,USER,PASSWORD);} public static void main(String[] args){Scanner sc=new Scanner(System.in);try(Connection con=getConnection()){System.out.println("1.Insert Book\n2.Search Book\n3.Display Available\n4.Issue Book");System.out.print("Enter choice: ");int c=sc.nextInt();sc.nextLine();if(c==1){System.out.print("Book ID: ");int id=sc.nextInt();sc.nextLine();System.out.print("Title: ");String t=sc.nextLine();System.out.print("Author: ");String a=sc.nextLine();System.out.print("Price: ");double p=sc.nextDouble();String q="INSERT INTO Book VALUES (?, ?, ?, ?, TRUE)";try(PreparedStatement ps=con.prepareStatement(q)){ps.setInt(1,id);ps.setString(2,t);ps.setString(3,a);ps.setDouble(4,p);ps.executeUpdate();System.out.println("Book inserted.");}}else if(c==2){System.out.print("Book ID: ");int id=sc.nextInt();try(PreparedStatement ps=con.prepareStatement("SELECT * FROM Book WHERE BookID=?")){ps.setInt(1,id);try(ResultSet rs=ps.executeQuery()){if(rs.next())System.out.println(rs.getInt("BookID")+" "+rs.getString("Title")+" "+rs.getString("Author")+" "+rs.getDouble("Price")+" "+rs.getBoolean("Availability"));else System.out.println("Book not found.");}}}else if(c==3){try(Statement st=con.createStatement();ResultSet rs=st.executeQuery("SELECT * FROM Book WHERE Availability=TRUE")){while(rs.next())System.out.println(rs.getInt("BookID")+" "+rs.getString("Title")+" "+rs.getString("Author")+" "+rs.getDouble("Price"));}}else if(c==4){System.out.print("Enter Book ID to issue: ");int id=sc.nextInt();try(PreparedStatement ps=con.prepareStatement("UPDATE Book SET Availability=FALSE WHERE BookID=?")){ps.setInt(1,id);ps.executeUpdate();System.out.println("Book availability updated.");}}}catch(SQLException e){System.out.println("Database error: "+e.getMessage());}sc.close();} }